const runnerBase = process.env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = process.env.AUTOMATION_RUNNER_TOKEN;
if (!runnerBase) throw new Error('AUTOMATION_RUNNER_BASE_URL is not configured');

const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};

const now = new Date().toISOString();
const dateStamp = now.replace(/[:]/g, '-');
const queueReportPath = `delivery-runs/queue-scan-${dateStamp}.md`;

const writeReport = async (relativePath, content) => {
  const response = await fetch(`${runnerBase}/reports/write`, {
    method: 'POST',
    headers,
    body: JSON.stringify({ relativePath, content }),
  });
  if (!response.ok) {
    const body = await response.text();
    throw new Error(`Runner report write failed: ${response.status} ${body}`);
  }
};

const repoStatusResponse = await fetch(`${runnerBase}/repo/status`, { headers });
if (!repoStatusResponse.ok) {
  const body = await repoStatusResponse.text();
  throw new Error(`Runner repo status failed: ${repoStatusResponse.status} ${body}`);
}
const repoStatus = await repoStatusResponse.json();

const response = $input.first().json;
const workItems = Array.isArray(response.results) ? response.results : [];

const extractExternalId = (text) => {
  const match = text.match(/External ID:\s*(TASK-\d+)/i);
  return match ? match[1] : null;
};

const extractAcceptance = (text) => {
  const match = text.match(/Acceptance Criteria([\s\S]*?)(Repo Metadata|Labels|$)/i);
  if (!match) return [];
  return match[1]
    .split(/\n+/)
    .map((line) => line.replace(/^[-*\d.\s]+/, '').trim())
    .filter(Boolean);
};

const extractLabels = (text) => {
  const match = text.match(/Labels([\s\S]*?)$/i);
  if (!match) return [];
  return match[1]
    .split(/\n+/)
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => line.replace(/^[-*\d.\s]+/, '').trim());
};

const extractSummary = (text) => {
  return text.split(/Acceptance Criteria/i)[0].replace(/\s+/g, ' ').trim();
};

const priorityOrder = { urgent: 0, high: 1, medium: 2, low: 3, none: 4 };
const candidates = workItems
  .map((item) => {
    const description = (item.description_stripped ?? '').trim();
    const externalId = extractExternalId(description);
    const acceptance = extractAcceptance(description);
    const labels = extractLabels(description);
    const summary = extractSummary(description);
    return {
      id: item.id,
      externalId,
      title: item.name,
      priority: item.priority ?? 'none',
      completedAt: item.completed_at ?? null,
      description,
      acceptance,
      labels,
      summary,
    };
  })
  .filter((item) => item.externalId)
  .filter((item) => !item.completedAt)
  .filter((item) => item.acceptance.length > 0)
  .filter((item) => item.description.includes('Repo Metadata'))
  .filter((item) => !item.labels.includes('lane:ops'))
  .sort((left, right) => {
    const leftPriority = priorityOrder[left.priority] ?? 99;
    const rightPriority = priorityOrder[right.priority] ?? 99;
    if (leftPriority !== rightPriority) return leftPriority - rightPriority;
    return String(left.title).localeCompare(String(right.title));
  });

if (repoStatus.branch !== 'main') {
  const content = [
    '# Plane Guarded Delivery Pipeline',
    '',
    `Generated: ${now}`,
    '',
    `Skipped because repo branch is \`${repoStatus.branch}\` instead of \`main\`.`,
  ].join('\n');
  await writeReport(queueReportPath, content);
  return [{ json: { generatedAt: now, skipped: true, reason: 'not-on-main', reportRelativePath: queueReportPath, repoStatus } }];
}

if (!repoStatus.clean) {
  const content = [
    '# Plane Guarded Delivery Pipeline',
    '',
    `Generated: ${now}`,
    '',
    'Skipped because the working tree is not clean.',
  ].join('\n');
  await writeReport(queueReportPath, content);
  return [{ json: { generatedAt: now, skipped: true, reason: 'dirty-worktree', reportRelativePath: queueReportPath, repoStatus } }];
}

if (candidates.length === 0) {
  const content = [
    '# Plane Guarded Delivery Pipeline',
    '',
    `Generated: ${now}`,
    '',
    'No eligible implementation-ready Plane tasks were found.',
  ].join('\n');
  await writeReport(queueReportPath, content);
  return [{ json: { generatedAt: now, skipped: true, reason: 'no-candidates', reportRelativePath: queueReportPath, repoStatus, candidates: [] } }];
}

const task = candidates[0];
const callJob = async (action, args, mode = 'sync', dedupeKey = '') => {
  const response = await fetch(`${runnerBase}/jobs`, {
    method: 'POST',
    headers,
    body: JSON.stringify({ action, args, mode, dedupeKey }),
  });
  const raw = await response.text();
  if (!response.ok && response.status !== 202) {
    throw new Error(`${action} failed: ${response.status} ${raw}`);
  }
  return raw ? JSON.parse(raw) : null;
};

const prepared = await callJob('delivery_prepare_task', [task.externalId, task.title, task.priority, task.summary, JSON.stringify(task.acceptance)]);
const preparedMeta = prepared?.stdout ? JSON.parse(prepared.stdout) : prepared;
const runDir = preparedMeta?.runDir;

const implemented = await callJob('delivery_implement_task', [runDir]);
const implementedMeta = implemented?.stdout ? JSON.parse(implemented.stdout) : implemented;

const published = await callJob('delivery_publish_task', [runDir]);
const publishedMeta = published?.stdout ? JSON.parse(published.stdout) : published;

let reviewJob = null;
if (publishedMeta?.pr?.number) {
  reviewJob = await callJob('pr_autofinish', [String(publishedMeta.pr.number)], 'async', `delivery-pr-autofinish-${publishedMeta.pr.number}`);
}

const reportPath = `${runDir}/pipeline-summary.md`;
const reportContent = [
  '# Plane Guarded Delivery Pipeline',
  '',
  `Generated: ${now}`,
  `Task: ${task.externalId} - ${task.title}`,
  `Run Directory: ${runDir}`,
  '',
  '## Repo Status At Intake',
  '',
  '```json',
  JSON.stringify(repoStatus, null, 2),
  '```',
  '',
  '## Prepared',
  '',
  '```json',
  JSON.stringify(preparedMeta, null, 2),
  '```',
  '',
  '## Implemented',
  '',
  '```json',
  JSON.stringify(implementedMeta, null, 2),
  '```',
  '',
  '## Published',
  '',
  '```json',
  JSON.stringify(publishedMeta, null, 2),
  '```',
  '',
  '## Review Job',
  '',
  '```json',
  JSON.stringify(reviewJob, null, 2),
  '```',
].join('\n');

await writeReport(reportPath, reportContent);

return [{
  json: {
    generatedAt: now,
    task,
    repoStatus,
    runDir,
    prepared: preparedMeta,
    implemented: implementedMeta,
    published: publishedMeta,
    reviewJob,
    reportRelativePath: reportPath,
  },
}];
